        const b = el.querySelector('.go'); busy(b, 'Saving…'); const x = el.querySelector('#fg_x').value; const body = { login: el.querySelector('#fg_u').value, password: p1 }; if (m === 'code') body.code = x; else if (m === 'backup') body.backup = x; else body.key = x;
