      el.querySelector('#cs_f').onsubmit = async e => { e.preventDefault(); const b = el.querySelector('.go'); busy(b, 'Setting up…'); try { const r = await api('setup', { method: 'POST', body: { code: (el.querySelector('#cs_k') || {}).value || '', company: el.querySelector('#cs_c').value, name: el.querySelector('#cs_n').value, login: el.querySelector('#cs_u').value, password: el.querySelector('#cs_p').value } }); ME.u = r.me; afterLogin(); } catch (er) { el.querySelector('#cs_e').textContent = er.message; busy(b); } };
